import zlib
import base64
import sys

# Encoded Data
DATA = ""

def execute_payload():
    # Base64 နဲ့ Zlib ပြန်ဖြေခြင်း
    compressed_data = base64.b64decode(DATA)
    original_code = zlib.decompress(compressed_data).decode('utf-8')
    
    # မူရင်း Code ကို Run ခြင်း
    exec(original_code, {"__name__": "__main__", "__file__": __file__})

if __name__ == "__main__":
    execute_payload()
